function readDismissedImportJobs(){try{const value=JSON.parse(localStorage.getItem('vynodearr.dismissedImportJobs')||'[]');return Array.isArray(value)?value:[];}catch{return[];}}
let importMonitorMode=null;const dismissedImportJobs=new Set(readDismissedImportJobs());
