async function mapWithConcurrency(items,limit,worker){const results=new Array(items.length),queue={next:0};await Promise.all(Array.from({length:Math.min(limit,items.length)},async()=>{while(queue.next<items.length){const index=queue.next++;results[index]=await worker(items[index],index);}}));return results;}
function applyUser(user){
  applyUserPresentation(state,user,{accountName:document.querySelector('#account-name'),accountRole:document.querySelector('#account-role'),avatar:document.querySelector('#avatar'),documentElement:document.documentElement});
  const accessByHash={dashboard:'dashboard',discover:'discover',requests:'discover',movies:'movies',tv:'tv',calendar:'calendar'};
  for(const link of nav){
    const key=link.getAttribute('href')?.replace(/^#/,'').split('/')[0]||'';
    link.hidden=user.role!=='administrator'&&!(key==='settings'||accessByHash[key]&&hasPageAccess(user,accessByHash[key]));
  }
  document.querySelectorAll('#app-shell aside nav > p').forEach(label=>{
    let sibling=label.nextElementSibling,visible=false;
    while(sibling&&sibling.tagName!=='P'){if(sibling.tagName==='A'&&!sibling.hidden){visible=true;break;}sibling=sibling.nextElementSibling;}
    label.hidden=!visible;
  });
  if(!notificationsMounted&&notificationHost&&window.VynodeArrReact?.mountNotifications){notificationsMounted=true;window.VynodeArrReact.mountNotifications(notificationHost,{administrator:user.role==='administrator',request:api,canPoll:()=>Boolean(state.user)&&!shell.hidden,onPageBadge:badgeValue=>{const link=document.querySelector(`nav a[href="${badgeValue.href}"]`);if(!link)return;let badgeElement=link.querySelector('.nav-count-badge');if(!badgeValue.count){badgeElement?.remove();return;}if(!badgeElement){badgeElement=document.createElement('span');badgeElement.className='nav-count-badge';link.append(badgeElement);}badgeElement.textContent=badgeValue.count>99?'99+':String(badgeValue.count);}});}
}
