  const extra=movie?`<label>Genre<select data-library-filter="genre"><option value="">All genres</option>${[...new Set(items.flatMap(item=>item.genres||[]).filter(Boolean))].sort().map(value=>option(value,filters.genre)).join('')}</select></label><label>Collection<select data-library-filter="collection"><option value="">All collections</option>${[...new Set(items.map(item=>item.collection).filter(Boolean))].sort().map(value=>option(value,filters.collection)).join('')}</select></label>`:`<label>Network<select data-library-filter="network"><option value="">All networks</option>${[...new Set(items.map(item=>item.network).filter(Boolean))].sort().map(value=>option(value,filters.network)).join('')}</select></label><label>Status<select data-library-filter="status"><option value="">All statuses</option>${[...new Set(items.map(item=>item.status).filter(Boolean))].sort().map(value=>option(value,filters.status)).join('')}</select></label>`;
  const letters=['#',...'ABCDEFGHIJKLMNOPQRSTUVWXYZ'],available=new Set(items.map(titleInitial));
