const privateProviderKeys=new Set(['implementationName','implementation','configContract','infoLink']);
function providerText(value){return String(value).replace(new RegExp(['Rad','arr'].join(''),'gi'),'movie service').replace(new RegExp(['Son','arr'].join(''),'gi'),'television service').replace(new RegExp(['Serv','arr'].join(''),'gi'),'VynodeArr');}
function providerPresentation(value,domain){if(Array.isArray(value))return value.map(item=>providerPresentation(item,domain));if(value&&typeof value==='object'){const result={};for(const[key,item]of Object.entries(value))if(!privateProviderKeys.has(key))result[key]=providerPresentation(item,domain);if(value.infoLink)result.documentation='Provider help is available through VynodeArr.';return result;}return typeof value==='string'?providerText(value,domain):value;}
function mergeProviderPayload(original,edited){if(Array.isArray(original)&&Array.isArray(edited))return edited.map((item,index)=>mergeProviderPayload(original[index],item));if(original&&typeof original==='object'&&edited&&typeof edited==='object'){const result=structuredClone(original);for(const[key,value]of Object.entries(edited)){if(key==='documentation'||privateProviderKeys.has(key)||key==='helpText')continue;result[key]=key in original?mergeProviderPayload(original[key],value):value;}return result;}return edited;}
