async function route(){
  if(shell.hidden)return;
  const currentRoute=parseRoute(location.hash),{parts,key}=currentRoute,preserveLibrary=preservesMountedLibrary(currentRoute,{movies:Boolean(document.querySelector('#movies-react')),tv:Boolean(document.querySelector('#tv-react'))});
  if(!canOpenRoute(state.user,key,parts)){const destination=firstPermittedHash(state.user);if(location.hash!==destination)location.hash=destination;return;}
  teardownRoute(window.VynodeArrReact,{preserveLibrary,document});
  updateNavigation(nav,key,document.body);
  const action=resolveRouteAction(currentRoute,{enginesConfigured:state.enginesConfigured,preserveLibrary,libraryStale:state.libraryStale});
  switch(action.name){
    case'redirect':location.hash=action.hash;return;
    case'skip':return;
    case'engineSetup':return showEngineSetup();
    case'discover':return showDiscoverV2();
    case'requests':return showRequestsReact();
    case'requestManagement':return showRequestManagementReact();
    case'operations':return showOperationsReact();
    case'library':return showMedia(action.kind);
    case'collections':return showCollectionsReact();
    case'addMedia':return showAddMediaReact();
    case'wanted':return showWantedReact();
    case'movieDetail':return showMovieDetailReact(action.id);
    case'tvDetail':return showTvDetailReact(action.id);
    case'queue':return showQueueReact();
    case'history':return showHistoryReact();
    case'calendar':return showCalendarReact();
    case'health':return showHealthReact();
    case'serviceSettings':return showServiceSettings(action.section,action.templateFilter);
    case'management':return showManagementReact();
    case'engineManagement':return showEngineManagement();
    case'account':return showAccountReact(action.section);
    case'system':return showSystemReact();
    default:return showDashboard();
  }
}
