    const readRules=()=>{const data=new FormData(form);return{titleContains:String(data.get('titleContains')||'').trim(),genres:data.getAll('genres'),year:Number(data.get('year')||0)||'',decade:Number(data.get('decade')||0)||'',collection:String(data.get('collection')||''),monitoring:String(data.get('monitoring')||''),availability:String(data.get('availability')||'')};};
    const hasSmartRules=rules=>Boolean(rules.titleContains||rules.genres.length||rules.year||rules.decade||rules.collection||rules.monitoring||rules.availability);
    const matches=(movie,rules)=>{const title=rules.titleContains.toLowerCase();return(!title||movie.title.toLowerCase().includes(title))&&(!rules.genres.length||rules.genres.every(genre=>(movie.genres||[]).includes(genre)))&&(!rules.year||movie.year===rules.year)&&(!rules.decade||movie.year>=rules.decade&&movie.year<rules.decade+10)&&(!rules.collection||movie.collection===rules.collection)&&(!rules.monitoring||(rules.monitoring==='monitored'?movie.monitoring!=='none':movie.monitoring==='none'))&&(!rules.availability||(rules.availability==='available'?movie.hasFile:!movie.hasFile));};
